using Microsoft.AspNetCore.Mvc; using MovieTicketBooking.Web.Services; using MovieTicketBooking.Web.Models;
namespace MovieTicketBooking.Web.Controllers;
public class AdminController:Controller {readonly MovieStore s; public AdminController(MovieStore s)=>this.s=s; bool Auth()=>HttpContext.Session.GetString("Admin")=="1"; public IActionResult Login()=>View(); [HttpPost] public IActionResult Login(string id,string password){if(id=="MOVIEADMIN"&&password=="MOVIEADMIN"){HttpContext.Session.SetString("Admin","1");return RedirectToAction("Index");}ViewBag.Error="Invalid admin credentials.";return View();} public IActionResult Logout(){HttpContext.Session.Remove("Admin");return RedirectToAction("Login");} public IActionResult Index(){if(!Auth())return RedirectToAction("Login");ViewBag.Movies=s.Movies;ViewBag.Theatres=s.Theatres;ViewBag.Shows=s.Shows;ViewBag.Bookings=s.Bookings;return View();} [HttpPost] public IActionResult AddMovie(Movie m){if(!Auth())return RedirectToAction("Login");m.MovieID=(m.MovieName[..Math.Min(2,m.MovieName.Length)]+"-"+Guid.NewGuid().ToString("N")[..6]).ToUpper();s.Movies.Add(m);s.Save();return RedirectToAction("Index");} [HttpPost] public IActionResult AddTheatre(Theatre t){if(!Auth())return RedirectToAction("Login");t.TheatreID=new Random().Next(1000,9999);s.Theatres.Add(t);s.Save();return RedirectToAction("Index");} [HttpPost] public IActionResult AddShow(Show x){if(!Auth())return RedirectToAction("Login");x.ShowID=new Random().Next(1000,9999);s.Shows.Add(x);s.Save();return RedirectToAction("Index");} [HttpPost] public IActionResult DeleteMovie(string id){if(!Auth())return RedirectToAction("Login");s.Movies.RemoveAll(x=>x.MovieID==id);s.Shows.RemoveAll(x=>x.MovieID==id);s.Save();return RedirectToAction("Index");} [HttpPost] public IActionResult CancelBooking(int id){if(!Auth())return RedirectToAction("Login");var b=s.Bookings.FirstOrDefault(x=>x.BookingID==id);if(b!=null)b.BookingStatus="Cancelled";s.Save();return RedirectToAction("Index");} }
